const input=document.getElementById("url-input"),output=document.getElementById("url-output");function encodeURL(){try{const t=input.value;if(!t)return output.textContent=i18n.t("common.enter_text");output.textContent=encodeURIComponent(t),output.style.color="var(--text)"}catch(t){output.textContent="\u274C \uC624\uB958: "+t.message,output.style.color="#ef4444"}}function decodeURL(){try{const t=input.value.trim();if(!t)return output.textContent=i18n.t("common.enter_url_encoded");output.textContent=decodeURIComponent(t),output.style.color="var(--text)"}catch{output.textContent=i18n.t("common.error_decoding"),output.style.color="#ef4444"}}function copyResult(){copyToClipboard(output.textContent).then(()=>showToast(i18n.t("common.copied")))}function downloadResult(){const t=output.textContent;if(!t||t===i18n.t("common.result_placeholder")||t.startsWith("\u274C"))return showToast(i18n.t("common.no_result"));downloadFile(t,"url-result.txt")}function clearAll(){input.value="",output.textContent=i18n.t("common.result_placeholder"),output.style.color="var(--text-muted)"}
